import{_ as e,o as n,c as r,ag as a}from"./chunks/framework.C5oN-8Wt.js";const p=JSON.parse('{"title":"安装导航实验环境","description":"","frontmatter":{},"headers":[],"relativePath":"v0.5.0-beta/setup/linux-environment/index.md","filePath":"v0.5.0-beta/setup/linux-environment/index.md"}'),o={name:"v0.5.0-beta/setup/linux-environment/index.md"};function s(i,t,l,d,g,c){return n(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="安装导航实验环境" tabindex="-1">安装导航实验环境 <a class="header-anchor" href="#安装导航实验环境" aria-label="Permalink to &quot;安装导航实验环境&quot;">​</a></h1><p>“录制信号定位”使用 GNSS-SDR 计算卫星定位结果。第一次做这项实验时，在 Master 里安装环境和定位样本。准备好以后可离线重复运行。</p><h2 id="选择安装位置" tabindex="-1">选择安装位置 <a class="header-anchor" href="#选择安装位置" aria-label="Permalink to &quot;选择安装位置&quot;">​</a></h2><ol><li>打开 <strong>Master 设置 → 实验环境</strong>。</li><li>查看页面显示的所需空闲空间。想把环境装到指定的盘，点击 <strong>选择位置并安装…</strong>，选一个已存在的本地文件夹，再点击 <strong>安装</strong>。接受默认位置时可直接点击 <strong>安装</strong>。</li><li>连接互联网并等待安装。Master 准备 Ubuntu 和 GNSS-SDR，再下载默认定位样本。样本压缩包约 <strong>1.15 GB</strong>，解压后的样本约 <strong>1.6 GB</strong>。环境和解压后的样本都存放在所选位置下的 <code>CNS Master Linux</code> 文件夹中。</li><li>如果 Windows 要求管理员确认，按系统提示操作。如果页面显示 <strong>等待重启</strong>，可以现在重启，也可以保存工作后重启。重启后重新打开 Master，回到 <strong>实验环境</strong>查看进度。</li><li>看到 <strong>环境已就绪</strong>，进入<a href="./../../learn/recorded-gnss/">录制信号定位</a>开始实验。</li></ol><h2 id="已有实验环境时补装样本" tabindex="-1">已有实验环境时补装样本 <a class="header-anchor" href="#已有实验环境时补装样本" aria-label="Permalink to &quot;已有实验环境时补装样本&quot;">​</a></h2><p>页面显示 <strong>待安装定位样本</strong> 时，保持联网，点击 <strong>补装样本</strong>。Master 会在现有环境的位置下载并解压样本。下载中断后，等页面恢复到待安装状态，再点一次即可重试。</p><p>学校机房如果需要管理员确认，请老师或机房管理员完成 Windows 的确认步骤。</p>',7)])])}const u=e(o,[["render",s]]);export{p as __pageData,u as default};
